function renderMedia(key){document.querySelector('#media-panel').innerHTML=media[key].map(([name,type,url])=>`<a href="${url}" target="_blank" rel="noopener">${name} <span aria-hidden="true">↗</span><small>${type}</small></a>`).join('')}
function tabs(selector,attribute,callback,panel){const buttons=[...document.querySelectorAll(selector)];buttons.forEach((button,i)=>{button.addEventListener('click',()=>{buttons.forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1});document.querySelector(panel).setAttribute('aria-labelledby',button.id);callback(button.dataset[attribute])});button.addEventListener('keydown',e=>{let j;if(e.key==='ArrowRight')j=(i+1)%buttons.length;if(e.key==='ArrowLeft')j=(i-1+buttons.length)%buttons.length;if(e.key==='Home')j=0;if(e.key==='End')j=buttons.length-1;if(j!==undefined){e.preventDefault();buttons[j].focus();buttons[j].click()}})})}
tabs('[data-media]','media',renderMedia,'#media-panel');renderMedia('tv');
