function renderTravel(key){document.querySelector('#travel-panel').innerHTML=travel[key].map(([type,title,price,note,url,label])=>`<article class="route"><span class="route-type">${type}</span><h3>${title}</h3><div class="route-price ${price.startsWith('от')?'':'compact'}">${price}</div><p>${note}</p><a href="${url}" target="_blank" rel="noopener">${label} <span>↗</span></a></article>`).join('')}
tabs('[data-city]','city',renderTravel,'#travel-panel');renderTravel('moscow');
const photoDialog=document.querySelector('#photo-dialog');
document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{const img=document.querySelector('#modal-photo');img.src=button.dataset.photo;img.alt=button.dataset.title;document.querySelector('#photo-title').textContent=button.dataset.title;photoDialog.showModal()}));
document.querySelector('#sources-button').addEventListener('click',()=>document.querySelector('#sources-dialog').showModal());
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});dialog.addEventListener('close',()=>document.body.style.overflow='');new MutationObserver(()=>{if(dialog.open)document.body.style.overflow='hidden'}).observe(dialog,{attributes:true,attributeFilter:['open']})});
